 if(!previous){for(const c of state.roster){const saved=await storage(env).get(owner,c.id);if(!saved)fail('An entrant is no longer in your saved collection. Refresh your roster and try again.');const summary=JSON.parse(saved.summary_json),traits=JSON.parse(saved.state_json).traits;if(JSON.stringify(c.summary.stats)!==JSON.stringify(summary.stats)||JSON.stringify(c.traits)!==JSON.stringify(traits)||c.name!==saved.name)fail('An entrant changed since it was loaded. Refresh your roster before creating the tournament.');}}
 else{const before=await decodeTournament(previous.state_json);const firstBefore=before.history.find(m=>m.results?.length),priorEngine=before.engineVersion??(firstBefore?firstBefore.results[0].combatVersion??1:10),firstAfter=state.history.find(m=>m.results?.length),afterEngine=state.engineVersion??(firstAfter?firstAfter.results[0].combatVersion??1:10);if(afterEngine!==priorEngine)fail('The combat engine is fixed for this cup.');if(JSON.stringify(normalizeArenaConditions(before.conditions??{time:before.night?'night':'day'}))!==JSON.stringify(normalizeArenaConditions(state.conditions??{time:state.night?'night':'day'})))fail('Tournament conditions are fixed once created.');if(JSON.stringify(normalizeDivision(before.filters))!==JSON.stringify(normalizeDivision(state.filters)))fail('Tournament filters are fixed once created.');if(before.done&&(!state.done||before.champion!==state.champion))fail('A completed tournament result cannot be changed.');for(const key of ['roster','stages','seed','night','progressionVersion'])if(JSON.stringify(before[key])!==JSON.stringify(state[key]))fail('Tournament entrants and stages are fixed once created. Start a new tournament to change them.');if(JSON.stringify(state.history.slice(0,before.history.length))!==JSON.stringify(before.history))fail('Previously saved match results cannot be changed.');}
